from lib import *
S = SS('v88')
steps = [
    step("镜像发了什么。路由把请求发给 prod,同时镜像一份给 shadow(100%),发 200 个 GET。客户端拿到的 200 个响应全是 prod 的,shadow 的响应被丢弃;shadow 收到 200 个请求。默认情况下 shadow 看到的 Host 是 127.0.0.1-shadow:端口,后缀加在主机名后、端口之前;设了 disable_shadow_host_suffix_append: true 之后 Host 是 127.0.0.1:端口,和 prod 看到的一样。", t=tl(S(1)), mark=lidx(S(1), '默认  '), done=lidx(S(1), 'suffix_append: true |'), b=bars([['客户端拿到 prod 响应', 200, '200'], ['客户端拿到 shadow 响应', 0, '0'], ['shadow 收到的请求', 200, '200']], 200, done=[0, 2], mark=[1]), kv=KV([['客户端', '只拿到 prod 的响应'], ['shadow', '收到 200 个,响应被丢弃'], ['Host 默认', '127.0.0.1-shadow:端口'], ['关掉后缀', 'Host 与 prod 相同']], ['Host 默认'])),
    step("shadow 出问题时客户端受不受影响(每种 400 个 GET,100 个/秒,镜像 100%)。不镜像:成功率 100.0%,p50 1.2 ms,p99 2.7 ms。shadow 正常:100.0%,p50 1.9 ms,p99 3.3 ms。shadow 每个请求 1 s:100.0%,p99 3.8 ms,shadow 收到 400 个。shadow 返回 500:100.0%,p99 3.5 ms。shadow 整个停了:100.0%,p99 3.3 ms,Envoy 发往 shadow 的请求数是 0(连接被拒绝)。p50 看起来不镜像更快(1.2 ms 对 1.9 ms),但开发中的另一次运行是 1.5 ms 对 1.7 ms,差异在运行间的抖动范围内;我没有重复足够多轮,不能说镜像本身有没有延迟代价。", t=tl(S(2)), mark=lidx(S(2), 'shadow 每个请求 1 s', 'shadow 返回 500', 'shadow 已停止'), done=lidx(S(2), '不镜像(对照)', 'shadow 正常'), b=bars([['不镜像 p99 ms', 2.7, '2.7'], ['shadow 正常 p99 ms', 3.3, '3.3'], ['shadow 慢 1 s p99 ms', 3.8, '3.8'], ['shadow 500 p99 ms', 3.5, '3.5'], ['shadow 已停 p99 ms', 3.3, '3.3']], 4, done=[0, 1], mark=[2, 3, 4]), kv=KV([['成功率', '五种场景全是 100.0%'], ['shadow 慢 1 s', '客户端 p99 3.8 ms'], ['shadow 返回 500', '客户端 p99 3.5 ms'], ['shadow 停止', '发往 shadow 的请求数 0']], ['成功率'])),
    step("runtime_fraction 控制镜像比例(每种 1000 个 GET,200 个/秒)。numerator 0:shadow 收到 0 个。10:收到 116 个(11.6%)。50:收到 537 个(53.7%)。100:收到 1000 个。实际比例围绕设定值波动,这次的两个中间值都比设定值高了一点,没有重复多轮,所以不能说它的偏差是多大。", t=tl(S(3)), mark=lidx(S(3), '10%  ', '50%  '), done=lidx(S(3), '0%  ', '100%  '), b=bars([['numerator 0 → shadow 收到', 0, '0'], ['numerator 10 → shadow 收到', 116, '116(11.6%)'], ['numerator 50 → shadow 收到', 537, '537(53.7%)'], ['numerator 100 → shadow 收到', 1000, '1000']], 1000, done=[0, 3], mark=[1, 2]), kv=KV([['设定 10%', '实际 11.6%'], ['设定 50%', '实际 53.7%'], ['设定 100%', '实际 100.0%'], ['设定 0', '实际 0']], ['设定 10%'])),
    step("shadow 变慢加熔断器(shadow 每个请求 2 s,300 个/秒持续 4 s,共 1200 个 GET)。默认熔断阈值(300 个/秒乘 2 s 约 600 个并发,低于默认的 1024 个连接):1200 个全部发到 shadow,溢出 0。shadow 集群 max_connections 5、max_pending_requests 5:发往 shadow 的请求只有 15 个,pending_overflow 1185,cx_overflow 18,shadow 实际收到 15 个。两种情况客户端成功率都是 100.0%,p99 分别 3.3 ms 和 2.8 ms。熔断器丢掉的镜像请求不影响客户端,但 shadow 只看到 1200 个里的 15 个,以为它看到了全量会得出错误的结论。", t=tl(S(4)), mark=lidx(S(4), '(b)max_connections 5'), done=lidx(S(4), '(a)默认熔断阈值'), b=bars([['默认阈值:shadow 收到', 1200, '1200'], ['限流后:shadow 收到', 15, '15'], ['限流后:pending_overflow', 1185, '1185'], ['限流后:cx_overflow', 18, '18']], 1200, done=[0], mark=[1, 2, 3]), kv=KV([['客户端成功率', '两种都是 100.0%'], ['默认阈值', '1200 个全部发到 shadow'], ['限住后', '1200 个只到 15 个'], ['丢弃方式', 'pending_overflow 1185']], ['限住后'])),
    step("镜像的写请求在 shadow 里真的执行了。客户端发 100 个 POST /pay,每个带 64 字节请求体,镜像 100%:客户端的 100 个响应全是 200 paid;prod 执行了 100 次写,shadow 也执行了 100 次写,收到的请求体长度都是 64 字节,共 100 个。镜像连请求体一起发,shadow 如果连着真实的数据库、消息队列或支付渠道,这些写会再执行一遍;shadow 要指向隔离的数据和下游,或者只镜像读请求。这个实验里 shadow 只是一个计数器,没有验证它写真实数据库会怎样。", t=tl(S(5)), mark=lidx(S(5), '客户端 POST 100 个'), done=lidx(S(5), '镜像连请求体一起发'), b=bars([['客户端收到的 200 响应', 100, '100'], ['prod 执行的写', 100, '100'], ['shadow 执行的写', 100, '100(重复)'], ['shadow 收到的请求体字节', 64, '64']], 100, done=[0, 1], mark=[2], cur=[3]), kv=KV([['prod', '执行 100 次写'], ['shadow', '也执行 100 次写'], ['请求体', '64 字节,完整转发'], ['要求', 'shadow 数据与下游必须隔离']], ['shadow'])),
]
A = mkartv('v88', 88, '微服务,服务网格,Envoy,流量镜像,shadow,灰度,真实验证,动画演示',
    '实测 Envoy 的流量镜像:客户端永远只拿到 prod 的响应;shadow 慢 1 s、返回 500、整个停了,客户端成功率都是 100.0%;镜像比例用 runtime_fraction 控制;shadow 的熔断器限住后 1200 个镜像请求只有 15 个到达;镜像的 POST 会在 shadow 里再执行一遍。',
    '想用线上真实流量验证新版本又不想影响用户,流量镜像是怎么工作的?shadow 慢了或挂了会不会拖累用户?镜像的写请求会怎样?这篇用 Envoy 1.39.3 的 request_mirror_policies 和本机后端逐项量出来。',
    [('100.0%', 'shadow 慢 1 s、返回 500 或整个停止时,客户端的成功率(五种场景都是这个值)'), ('15 / 1200', 'shadow 集群 max_connections 5 时,实际到达 shadow 的镜像请求'), ('100 次', '镜像 100% 时,100 个 POST 在 shadow 里再执行的写次数')],
    [('镜像做了什么', '<p>请求复制一份发给 shadow,响应丢弃,客户端只拿到 prod 的响应;shadow 默认看到带 -shadow 后缀的 Host。</p>'),
     ('shadow 出问题', '<p>慢、返回 500、整个停止,客户端都不受影响,镜像是发出去就不管。</p>'),
     ('镜像比例', '<p>runtime_fraction 按请求随机抽样,实际比例围绕设定值波动。</p>'),
     ('shadow 的熔断器', '<p>shadow 集群的熔断器限住后,超出的镜像请求直接丢掉,shadow 看到的不是全量。</p>'),
     ('写请求', '<p>镜像连请求体一起发,写请求在 shadow 里真的会再执行一遍,shadow 必须有隔离的数据与下游。</p>')],
    steps,
    [ENV_V + '。Envoy 1.39.3(--concurrency 1),request_mirror_policies 与 runtime_fraction 的静态配置;prod 与 shadow 是本机的 Python 服务;每种场景只跑了一次,毫秒数每次运行略有不同(例如 runtime_fraction 10% 的实际比例在两次运行里是 11.4% 和 11.6%);镜像流量在 shadow 一侧的计数用 Python 服务自己统计',
     '没有验证:镜像请求的响应对比(diff)工具;镜像对 prod 一侧资源(Envoy 的 CPU、连接数)的额外开销;Istio 的 mirror 与 mirrorPercent 配置;shadow 返回 500 以外的错误类型对 Envoy 统计的影响;镜像 HTTP/2 或 gRPC 流式请求;镜像请求体很大时的缓冲行为;shadow 写真实数据库时的数据污染(本篇 shadow 只是计数器)'],
    '流量镜像')
